function drawEnergyLevels(containerId, energies) {
    const glowGreen = '#39ff14';
    const textGreen = '#00cc44';
    const dimGreen = '#008822';
    const margin = { top: 32, right: 24, bottom: 44, left: 64 };
    const width = 640;
    const height = 340;
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;
    const container = d3.select(containerId);
    container.selectAll('*').remove();

    const names = ['E₀', 'E₁', 'E₂', 'E₃'];
    const data = energies.map((energy, i) => ({ name: names[i], energy }));
    if (data.length !== 4 || data.some(d => !Number.isFinite(d.energy))) return;

    const yMin = d3.min(data, d => d.energy);
    const yMax = d3.max(data, d => d.energy);
    const yPad = Math.max((yMax - yMin) * 0.2, 0.1);
    const xScale = d3.scalePoint().domain(names).range([0, innerWidth]).padding(0.5);
    const yScale = d3.scaleLinear().domain([yMin - yPad, yMax + yPad])
        .nice().range([innerHeight, 0]);

    const svg = container.append('svg')
        .attr('viewBox', `0 0 ${width} ${height}`)
        .attr('preserveAspectRatio', 'xMidYMid meet')
        .attr('role', 'img')
        .attr('aria-label', 'Four predicted energy levels in GeV');
    svg.append('title').text(data.map(d => `${d.name}: ${d.energy.toFixed(4)} GeV`).join(', '));
    const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);
    g.append('g').attr('transform', `translate(0,${innerHeight})`)
        .call(d3.axisBottom(xScale)).style('font-size', '14px');
    g.append('g').call(d3.axisLeft(yScale)).style('font-size', '12px');
    g.selectAll('.domain, .tick line').attr('stroke', dimGreen);
    g.selectAll('.tick text').attr('fill', textGreen);
    g.append('text').attr('transform', 'rotate(-90)')
        .attr('y', -48).attr('x', -innerHeight / 2)
        .attr('text-anchor', 'middle').attr('fill', textGreen)
        .style('font-size', '12px').text('Energy [GeV]');

    g.selectAll('.energy-level').data(data).join('line')
        .attr('class', 'energy-level')
        .attr('x1', d => xScale(d.name) - 32)
        .attr('x2', d => xScale(d.name) + 32)
        .attr('y1', d => yScale(d.energy)).attr('y2', d => yScale(d.energy))
        .attr('stroke', glowGreen).attr('stroke-width', 3);
    g.selectAll('.energy-label').data(data).join('text')
        .attr('class', 'energy-label')
        .attr('x', d => xScale(d.name)).attr('y', d => yScale(d.energy) - 10)
        .attr('text-anchor', 'middle').attr('fill', glowGreen)
        .style('font-size', '13px').text(d => d.energy.toFixed(4));
}
